例子 - SpringBoot 集成代码地址
pkl-springPkl-Spring 通过 boot-starter 配置将 Pkl 引入到 Spring Boot 中，具体的代码如下
spring.factories
org.springframework.boot.env.PropertySourceLoader=org.pkl.spring.boot.PklPropertySourceLoaderorg.springframework.boot.autoconfigure.EnableAutoConfiguration=org.pkl.spring.boot.PklAutoConfiguration

PklPropertySourceLoader
public class PklPropertySourceLoader implements PropertySourceLoader {  @Override  public String[] getFileExtensions() {    return new String[] {"pkl", "pcf"};  }  @Override  public List&lt;PropertySource&lt;?&gt;&gt; load(String propertySourceName, Resource resource)      throws IOException {    var text = StreamUtils.copyToString(resource.getInputStream(), StandardCharsets.UTF_8);    PModule module;    try (var evaluator = EvaluatorBuilder.preconfigured().build()) {      module = evaluator.evaluate(ModuleSource.create(resource.getURI(), text));    }    var result = new LinkedHashMap&lt;String, Object&gt;();    module.getProperties().forEach((name, value) -&gt; flatten(name, value, result));    return List.of(new MapPropertySource(propertySourceName, result));  }  private static void flatten(      String propertyName, Object propertyValue, Map&lt;String, Object&gt; result) {    if (propertyValue instanceof Composite) {      flatten(propertyName, ((Composite) propertyValue).getProperties(), result);    } else if (propertyValue instanceof Map&lt;?, ?&gt;) {      var map = (Map&lt;?, ?&gt;) propertyValue;      if (map.isEmpty()) {        result.put(propertyName, Collections.emptyMap());      } else {        map.forEach((name, value) -&gt; flatten(propertyName + '.' + name, value, result));      }    } else if (propertyValue instanceof Collection) {      var collection = (Collection&lt;?&gt;) propertyValue;      if (collection.isEmpty()) {        result.put(            propertyName,            propertyValue instanceof Set ? Collections.emptySet() : Collections.emptyList());      } else {        var index = 0;        for (var element : collection) {          flatten(propertyName + '[' + index++ + ']', element, result);        }      }    } else {      result.put(propertyName, propertyValue);    }  }}

